import{_ as t,o,c as a,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Tax types (developer)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tax types (developer) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/tax-types"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tax types (developer) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/tax-types"}]]},"headers":[],"relativePath":"developer-guide/tax-types.md","filePath":"developer-guide/tax-types.md","lastUpdated":1788225865000}'),c={name:"developer-guide/tax-types.md"};function n(i,e,s,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="tax-types-developer" tabindex="-1">Tax types (developer) <a class="header-anchor" href="#tax-types-developer" aria-label="Permalink to &quot;Tax types (developer)&quot;">​</a></h1><p>Jurisdiction-agnostic tenant catalog under Accounting. Pakistan FBR-style sections are <strong>test data only</strong> (<code>authority_reference</code>), not hardcoded logic.</p><h2 id="data-model" tabindex="-1">Data model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data model&quot;">​</a></h2><p>Table <code>tax_types</code> (<code>BelongsToTenant</code>, soft deletes):</p><ul><li><code>kind</code>: <code>sales_tax</code> | <code>withholding</code></li><li><code>direction</code>: <code>add_on_sale</code> | <code>deduct_on_payment_in</code> | <code>deduct_on_payment_out</code></li><li><code>rate</code>, <code>calculation_base</code>, optional GL FKs, <code>authority_reference</code>, <code>is_active</code></li></ul><p>Billing lines: nullable <code>tax_type_id</code> on invoice, credit note, quotation, estimate, and PO line tables.</p><p>Withholding columns on <code>customer_payments</code> and <code>expenses</code>: <code>withholding_tax_type_id</code>, <code>withholding_amount</code>, <code>withholding_authority_reference</code>.</p><p>Counterparty defaults: <code>contacts.default_withholding_tax_type_id</code>, <code>vendors.default_withholding_tax_type_id</code>.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><ul><li><code>TaxTypeService</code> — CRUD + <code>assertActiveForApply()</code> + <code>calculateWithholdingAmount()</code></li><li><code>TaxTypeResolver</code> — resolves line <code>tax_rate</code> from active sales tax types when Accounting is entitled</li><li><code>CashMovementJournalService::createAndPostLines()</code> — multi-line auto-posted journals</li></ul><h3 id="gl-posting" tabindex="-1">GL posting <a class="header-anchor" href="#gl-posting" aria-label="Permalink to &quot;GL posting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Journal</th></tr></thead><tbody><tr><td>Invoice send</td><td>Dr AR / Cr Revenue / Cr Tax Payable (<code>2100</code>)</td></tr><tr><td>Credit note apply</td><td>Reverse split</td></tr><tr><td>Payment post (with WHT)</td><td>Dr Deposit (net) / Dr WHT Receivable (<code>1150</code>) / Cr AR (gross)</td></tr><tr><td>Expense pay (with WHT)</td><td>Dr Expense (gross) / Cr Cash (net) / Cr WHT Payable (<code>2150</code>)</td></tr></tbody></table><p>Payment <code>amount</code> remains gross-to-AR; withholding reduces deposit only.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-tax-types">tenant-v1-tax-types</a>. Routes: <code>module:accounting</code> + existing <code>accounting.*</code> permissions (no new slugs).</p><h2 id="catalog-versions" tabindex="-1">Catalog versions <a class="header-anchor" href="#catalog-versions" aria-label="Permalink to &quot;Catalog versions&quot;">​</a></h2><ul><li><code>accounting</code> <strong>1.7.0</strong> — tax types CRUD, starter WHT accounts, invoice/credit tax split</li><li><code>accounting</code> <strong>1.7.1</strong> — withholding on payments/expenses, counterparty defaults</li><li><code>accounting</code> <strong>1.7.2</strong> — list API fix: <code>direction=asc|desc</code> sorts; enum values filter by tax direction</li><li><code>invoices</code> <strong>1.8.1</strong> — <code>tax_type_id</code> on billing lines</li></ul><p>List query: use <code>sort</code> + <code>direction</code> (<code>asc</code>/<code>desc</code>) for ordering; pass tax direction enum values to filter. See <a href="/api/tenant-v1-tax-types">API</a>.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>tests/Feature/Tenant/Accounting/TaxTypeTest.php</code></li><li><code>tests/Feature/Tenant/Accounting/PaymentWithholdingTest.php</code></li><li><code>tests/Feature/Tenant/Accounting/ExpenseWithholdingTest.php</code></li><li><code>tests/Feature/Tenant/CustomerInvoice/CustomerInvoiceAccountingTest.php</code> (tax split)</li></ul><p>Playwright: <code>e2e/tests/accounting/tax-types.spec.ts</code></p><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><p>Country template imports, formula/filer engines, payroll statutory tax, WHT certificates, multi-jurisdiction per contact.</p>',23)])])}const g=t(c,[["render",n]]);export{h as __pageData,g as default};
